def expand_chapter4(add_heading, add_para, add_table):
    add_heading('4.1.1 输入契约与字段规范化', 3)
    add_para('导入函数先读取 CSV 表头，再按照 REQUIRED_FIELDS 检查六个字段是否全部存在。timestamp 允许以 Z 结尾的 UTC 字符串，程序转换为带时区意义的 ISO 表达；数值字段通过 float 转换并拒绝 NaN、正负无穷；station_id 去除两端空白后必须非空。这样的规范化把下游算法面对的对象限定为结构稳定的字典，减少算法代码同时处理字符串、空值和异常编码的分支。')
    add_table('表 4.1 输入字段校验规则', ['字段','解析规则','非法情况','处理结果'], [
        ('timestamp','datetime.fromisoformat，兼容结尾 Z','空值、非法日期','计入 invalid_rows 并跳过'),('station_id','去除空白并保留字符串','空字符串','计入 invalid_rows 并跳过'),('irradiance_w_m2','有限浮点数','NaN、无穷、负值','计入 invalid_rows 和 negative_rows'),('ambient_temp_c','有限浮点数','空值或非数字','计入 invalid_rows'),('module_temp_c','有限浮点数','空值或非数字','计入 invalid_rows；真实源注明代理'),('power_kw','有限浮点数','NaN、无穷、负值','计入 invalid_rows 和 negative_rows')])
    add_heading('4.1.2 重复、排序和质量统计', 3)
    add_para('重复识别键为 (timestamp, station_id)。程序使用字典保存最新行，遇到相同键时增加 duplicate_rows 并覆盖旧值，最后按 timestamp、station_id 排序。保留最后一条是一个明确的项目决策：它不假设重复行平均值代表真实测量，也不让重复行悄悄进入后续模型。运行响应同时返回 input_rows、valid_rows、invalid_rows、duplicate_rows 和 negative_rows，前端可据此解释“导入了多少”和“删掉了什么”。')
    add_heading('4.1.3 效率代理与时间周期特征', 3)
    add_para('效率代理定义为 efficiency_proxy = power_kw / max(irradiance_w_m2, 1)。分母使用 1 的下限是为了避免夜间或极低辐照度记录产生除零错误，同时不把极低辐照度下的巨大比值误当成高质量效率。该字段用于相对比较和异常筛查，不是经过组件额定功率、温度系数和逆变器损耗校准的物理效率。时间特征将小时转换为角度，再生成 sin(angle) 和 cos(angle)，使 23 点与 0 点在特征空间中保持相邻。')
    add_table('表 4.2 特征向量组成', ['位置','特征','缩放或计算','解释'], [
        ('1','irradiance_w_m2','除以 1000','把 W/m² 置于较稳定的数值范围'),('2','ambient_temp_c','除以 50','环境温度缩放'),('3','module_temp_c','除以 80','模块温度字段或代理的缩放'),('4','power_kw','除以 100','功率缩放'),('5','efficiency_proxy','直接使用','相对效率线索'),('6','sin(hour angle)','sin(2πhour/24)','日周期连续表示'),('7','cos(hour angle)','cos(2πhour/24)','日周期连续表示')])
    add_heading('4.2.1 K-Means 初始化与迭代', 3)
    add_para('项目内 K-Means 首先使用固定随机种子 42 从样本中抽取 k 个初始中心。每次迭代计算每条记录到各中心的欧氏距离，把记录分配给最近中心，再按簇内各维度平均值更新中心。最多迭代 40 次；当一轮分配没有标签变化时提前停止；空簇保留旧中心，避免因为某一簇暂时没有成员导致维度丢失。k 会被限制在 1 到样本数之间，接口层进一步限制为 2 到 8。')
    add_para('聚类输出是工况标签和中心向量。标签编号本身没有业务含义，不能把 cluster_id=0 直接解释成“正常”或“白天”；需要结合中心向量、曲线和站点分布解释。页面显示的是工况数量和记录分布，论文用“工况”而不是“故障类别”，以避免把无监督聚类结果写成经过标注的诊断分类。')
    add_heading('4.2.2 聚类参数与可复现性', 3)
    add_para('运行参数通过 RunRequest 进入服务，k 默认 3，污染率默认 0.05，随机种子固定为 42 并写入 params_json。将参数写入运行记录的意义是让同一数据集在多次运行时能够比较，而不是依赖当前前端输入框。由于 K-Means 的初始中心和孤立森林的随机切分都使用确定的随机源，固定环境和输入后可以复算主要输出；这仍然不等于不同 Python、NumPy 或 Spark 版本之间每一个浮点数都完全相同。')
    add_heading('4.3.1 孤立树的构造', 3)
    add_para('孤立森林实现从特征行中最多抽取 64 条样本，依据样本规模计算最大深度。每棵树随机选择仍有变化的特征，在最小值和最大值之间生成随机切分点，把样本递归分成左右两组。样本只有一条、深度用尽、所有维度相同或切分后某一侧为空时，节点成为外部节点。这样处理了小样本和常量特征的边界，不会因为无法继续切分而产生空指针。')
    add_para('对每条记录，算法累加其在所有树中的路径长度，并用平均路径长度归一化得到原始分数，再将当前批次的分数线性映射到 0 至 1。路径越短的记录越容易被认为孤立。项目没有声称这个分数具有跨数据集的绝对物理意义，也没有把 0.85 当作通用安全阈值；0.85 只用于当前页面的高等级显示，异常筛选仍由当前运行的污染率分位位置和分数大于零共同决定。')
    add_heading('4.3.2 分工况检测和告警生成', 3)
    add_para('process_rows 先完成全量特征和聚类，再按 cluster_id 分组调用 isolation_scores，最后把每个子集的分数写回原记录顺序。阈值取排序后与污染率对应的位置，只有 score >= threshold 且 score > 0 才标记为异常。服务层写入 records 后立即为异常记录插入 alerts，消息包含站点和时间，便于从告警回到具体记录。告警并不是第二个独立模型，它是检测结果的面向运维展示层。')
    add_heading('4.3.3 Spark 适配器与一致性检查', 3)
    add_para('Spark 适配器的职责是将 CSV 送入集群并完成真实的分布式执行证据。它尝试导入 PySpark，读取 SPARK_MASTER_URL，写入 HDFS 探针并回读行数；PySpark 不存在时明确抛出“未执行 Spark 任务”的错误，而不是自动退回本地后报告 cluster 成功。服务在 cluster 模式中仍按同一输入契约读取源文件，并将 Spark 返回的记录结果写入 MySQL。集群证据中 1686 行输入、1686 行 HDFS 回读、1686 条 MySQL records 和 85 条 alerts 一致。')
    add_heading('4.3.4 复杂度与运行边界', 3)
    add_para('清洗阶段主要是一次遍历和字典去重，时间复杂度接近 O(n)，空间复杂度为有效记录数量。K-Means 的主要成本约为迭代次数、样本数、k 和特征维数的乘积；孤立森林成本受树数、抽样规模和树深度影响，项目将抽样规模限制在 64、树数限制在 20 至 80 之间。当前实现适合课程规模和中小批次数据，长期高并发、百万级连续流和模型在线更新没有在本轮验收中宣称完成。')


def expand_chapter5(add_heading, add_para, add_table):
    add_heading('5.1.1 服务启动与目录准备', 3)
    add_para('FastAPI 在 startup 事件中调用 ensure_ready，创建 runtime 目录并初始化数据库。数据库路径由 M10_DATABASE_URL 决定，便携模式要求 sqlite:/// 前缀，集群模式使用 mysql+pymysql URL。服务把 frontend 挂载到 /static，把项目 data 目录挂载到 /data，根路径返回 frontend/index.html。启动失败时不创建假数据，页面会显示服务尚未连接，启动器也会提示后端入口、目录或环境问题。')
    add_heading('5.1.2 数据导入实现', 3)
    add_para('导入接口使用 UploadFile 接收文件，并在服务层限制上传大小不超过 25 MB。文件先被完整读入内存，随后由 read_csv_bytes 解码和清洗；成功后计算原始字节 SHA-256，写入 datasets 表，再将原始字节保存为 dataset-{id}.csv。synthetic_demo 参数只记录数据性质，不改变算法；页面勾选演示数据时调用同一接口，但把该标记置为真。真实 PVDAQ 预置入口使用项目内规范化文件，不从页面临时下载远程数据。')
    add_heading('5.1.3 运行状态与事务边界', 3)
    add_para('创建运行时先写入一条 running 记录，再执行 local 或 cluster 处理。写入 records、alerts 和 completed 状态在同一个数据库连接上下文中提交；异常时执行回滚并将 processing_runs 更新为 failed。SQLite 连接启用外键，MySQL 适配层把问号占位符转换为参数占位符，并在启动时处理索引和字段类型。这样的实现重点是保持“有运行就有状态”，而不是只在接口返回中暂存结果。')
    add_table('表 5.1 后端服务操作与持久化', ['操作','主要函数/接口','写入对象','错误处理'], [
        ('导入','POST /api/datasets/import','datasets、runtime/uploads','400 + 可读 detail'),('创建运行','POST /api/runs / run_dataset','processing_runs','failed + error_message'),('保存检测结果','run_dataset 内批量 INSERT','records','事务回滚'),('生成告警','is_anomaly 为真时 INSERT','alerts','随运行事务提交'),('查询概览','/overview、/metrics/overview','只读聚合','运行不存在返回 404'),('查询明细','/records、/alerts','只读列表','limit 限制 1—5000')])
    add_heading('5.1.4 结果查询和分页边界', 3)
    add_para('overview 使用 SQL 聚合计算 total、anomalies、avg_power 和 avg_efficiency，并按 cluster_id 统计工况数量。records 支持 anomalies_only、station_id 和 limit，默认返回 500 条，最大 5000 条；页面的曲线和异常列表只使用当前运行返回的数据，不对缺失字段进行猜测。alerts 按 id 倒序返回，便于最新告警优先显示。对于更大数据量，当前版本还没有实现真正的游标分页和异步导出，这一限制记录在交付边界中。')
    add_heading('5.2.1 前端状态模型', 3)
    add_para('前端维护 runs、latestRun、overview、timeseries、anomalies 和 alerts 六类状态。页面加载时先请求 health 和 runs，再并行请求当前运行的 overview、records 和 alerts；如果没有完成运行，则显示空状态和导入提示。字段读取使用 pick 函数兼容少量不同后端命名，展示前使用 escapeHtml，避免站点编号或消息文本直接插入 HTML。')
    add_heading('5.2.2 曲线、工况和异常展示', 3)
    add_para('SVG 曲线把记录顺序映射到横坐标，把功率、辐照度或效率代理映射到纵坐标，并根据当前数据范围生成网格线和刻度。异常点以红色圆圈标注，不额外绘制一个“预测正确率”指标。工况分布使用记录数量计算横向条形图，异常表格显示时间、站点、工况、功率、效率代理、异常分数和等级；告警中心展示高、中、已处理数量以及来自后端的消息。')
    add_heading('5.2.3 导入与运行交互', 3)
    add_para('导入页面允许用户选择本地 CSV，也可以勾选项目内固定种子演示数据或 PVDAQ 真实切片。提交前检查三者至少选择一种；提交后按照“提交—清洗与特征计算—工况聚类—异常检测与告警—处理完成”更新进度。进度条用于解释服务当前阶段，不代表后台已经异步排队；当前接口是同步处理，长任务和取消操作尚未实现。')
    add_heading('5.3.1 启动脚本与日志', 3)
    add_para('start.cmd 和 stop.cmd 是 Windows 交付入口的基础文件。启动脚本检查项目目录、日志目录、后端模块和端口参数，再启动 Uvicorn 并把进程号写入 runtime/m10.pid；停止脚本只结束该 pid 文件指向的进程，不扫描和结束用户其他 Python 进程。当前脚本在 macOS 上只做静态存在性和内容检查，尚未在 Windows x64 上完成双击、解压、端口冲突和重启验证。')
    add_heading('5.3.2 Docker 组件与共享卷', 3)
    add_para('cluster profile 包含 mysql、namenode、datanode、spark-master、spark-worker 和 api 六类服务。API 和 Spark worker 使用 m10-runtime 共享卷，确保 worker 能读取 API 保存的 dataset-{id}.csv；HDFS 使用 name/data 两个卷保存节点数据；MySQL 使用 mysql-data 保存数据库文件。Docker 只承担开发和集群联调职责，客户 Windows 模式不要求安装 Docker。')
    add_table('表 5.2 集群服务与验收证据', ['服务','版本/角色','实际职责','证据'], [
        ('api','项目镜像，cluster 模式','HTTP 接口与结果写入','/api/health 返回 mode=cluster'),('spark-master','Spark 3.5.3','接收应用并调度 worker','Spark UI 显示 alive worker'),('spark-worker','Spark 3.5.3','执行 CSV/Parquet 处理','完成应用状态 FINISHED'),('namenode/datanode','Hadoop 3.2.1','保存 HDFS 探针和 Parquet','hdfs_rows=1686'),('mysql','MySQL 8.4','持久化 runs/records/alerts','records=1686、alerts=85')])
    add_heading('5.3.3 安全与数据边界', 3)
    add_para('当前系统面向本机或受控内网演示，接口没有账号认证，CORS 采用宽松配置，不能直接暴露公网。上传文件通过大小限制和字段校验控制输入，源文件落在项目 runtime 目录，不使用用户提供的路径作为任意文件名；前端展示文本经过 HTML 转义。若进入真实生产环境，还需要补充身份认证、角色权限、HTTPS、审计日志、上传病毒扫描、密钥管理和更严格的跨域策略，本轮不把这些未实现能力写成完成项。')


